let playerDraft=null,playerId=null,playerMovement=null;
function openPlayer(id,keepNavigation=false){
 const previousPane=keepNavigation?$('playerEditor').querySelector('[data-pane][aria-selected="true"]')?.dataset.pane:null;
 pendingDocumentaryClubs=[];playerPhotoBusy=false;
 playerId=id;const original=s.players.find(p=>p.id===id);playerDraft=structuredClone(original||{name:'Novo jogador',club:Number.isInteger(editorClub)?editorClub:null,position:'MED',quality:60,salary:3000,status:Number.isInteger(editorClub)?'Activo':'Sem clube'});
 playerDraft.internationalRecords=Engine.internationalRows(playerDraft);
 Documentary.unifySources(playerDraft);
 const p=playerDraft;playerDraft.attributes=Object.fromEntries(Object.keys(Engine.attributes).map(k=>[k,Engine.attr(p,k)]));if(!playerDraft.positionFamiliarity)playerDraft.positionFamiliarity=Object.fromEntries(Engine.positions.map(pos=>[pos,pos===p.position?100:(p.secondaryPositions||[]).includes(pos)?90:Engine.group(pos)===Engine.group(p.position)?70:0]));playerDraft.positionFamiliarity[p.position]=100;playerDraft.quality=Engine.gameOverall(playerDraft);playerMovement={type:p.loan?'Empréstimo':'Automático',date:mode==='career'?Engine.date(s):'',fee:'',notes:'',parentClub:p.loan?.parentClub??(p.club??''),loanStart:p.loan?.startDate||'',loanEnd:p.loan?.endDate||'',loanFee:p.loan?.fee??'',purchaseType:p.loan?.purchaseType||'Sem opção',purchaseFee:p.loan?.purchaseFee??''};
 const field=(key,label,type='text',min=0,max=1e10,extra='')=>`<label>${label}<input name="${key}" type="${type}" value="${esc(p[key]??'')}" ${type==='number'?`min="${min}" max="${max}" step="1"`:'maxlength="500"'} ${['name','salary'].includes(key)?'required':''} ${extra}></label>`;
 const select=(key,label,values,def)=>`<label>${label}<select name="${key}">${options(values,p[key]||def||values[0])}</select></label>`;
 const pane=(id,content)=>`<section class="player-pane" id="pp-${id}" ${id==='perfil'?'':'hidden'}>${content}</section>`;
 const playerClubOptions=current=>`<option value="" ${current===null||current===undefined?'selected':''}>— Sem clube —</option>`+s.clubs.map(c=>`<option value="${c.id}" ${c.id===current?'selected':''}>${esc(c.name)}</option>`).join('');
 const gameGroups=[
  ['Técnicos',['finishing','touch','passing','dribbling','heading']],
  ['Mentais',['decisions','composure','anticipation','positioning','teamwork']],
  ['Físicos',['pace','acceleration','stamina','strength','agility']],
  ['Guarda-redes',['gkReflexes','gkHandling','gkOneOnOne']],
  ['Perfil de simulação',['consistency','professionalism','injuryRisk','reputation','ambition']]
 ];
 const gameFields=gameGroups.map(([title,keys])=>`<section class="game-attribute-group"><h4>${title}</h4><div class="player-grid">${keys.map(k=>`<label>${Engine.attributes[k]}<input name="attr-${k}" type="number" min="1" max="20" step="1" required value="${p.attributes[k]}"></label>`).join('')}</div></section>`).join('');
 $('playerEditor').innerHTML=`<div class="dialog-head player-navigation"><button type="button" id="playerPrevious" aria-label="Jogador anterior">← Anterior</button><div><span class="eyebrow">PLANTEL E STAFF</span><h2>Editor de jogador</h2></div><button type="button" id="playerNext" aria-label="Jogador seguinte">Seguinte →</button><button type="button" id="playerClose" aria-label="Fechar ficha">×</button></div><form id="playerForm"><div id="playerNavigationPrompt" class="toolbar" role="status"></div><div id="playerIdentityHeader"></div><div class="player-layout"><div><div id="playerSticker"></div><p class="muted">Pré-visualização das alterações. Guarda para as aplicar ${mode==='database'?'à Mestre':'a esta carreira'}.</p><div id="documentCompleteness" class="document-completeness"></div><div id="playerSummary" class="player-summary"></div></div><div class="player-details"><div class="player-tabs" role="tablist" aria-label="Ficha do jogador">${[['perfil','Identidade'],['contrato','Contrato'],['internacional','Internacional'],['fontes','Notas / Fontes'],['media','Imagem / Cromo'],['carreira','Percurso'],['changes','Registo de edições'],['jogo','Simulação'],['stats','Estatísticas do jogo']].map(([v,t],i)=>`<button type="button" role="tab" aria-selected="${i===0}" aria-controls="pp-${v}" id="pt-${v}" data-pane="${v}" class="${['jogo','stats'].includes(v)?'simulation-tab':'documentary-tab'}">${t}</button>`).join('')}</div>
 ${pane('perfil',`<div class="data-scope-note"><b>Dados do mundo real</b><span>Identidade, características, posição, clube e informação documental. Estes campos não tentam atribuir uma nota subjectiva à qualidade real do jogador.</span></div><h3>Identidade</h3><div class="player-grid">${field('fullName','Nome completo')}${field('name','Nome conhecido')}${field('birthDate','Data de nascimento','date')}${field('birthPlace','Local de nascimento')}<p class="field-help wide">A idade é calculada automaticamente a partir da data de nascimento. Se a data oficial não estiver disponível, a idade fica por indicar e não aparece no cromo.</p><label class="country-choice">Nacionalidade principal${countrySelect('nation',p.nation)}<span id="nationFlagPreview" class="country-choice-preview"></span></label><label class="country-choice">Segunda nacionalidade${countrySelect('secondNation',p.secondNation)}<span id="secondNationFlagPreview" class="country-choice-preview"></span></label></div><h3>Dados futebolísticos</h3><div class="player-grid">${field('height','Altura (cm)','number',100,230)}${field('weight','Peso (kg)','number',30,200)}${select('foot','Pé preferido',['Direito','Esquerdo','Ambos'])}${select('position','Posição principal',Engine.positions)}${field('number','N.º camisola','number',0,99)}${select('status','Estado',['Activo','Lesionado','Emprestado','Sem clube','Retirado'])}<label>Clube onde joga<select name="club" id="playerClub">${playerClubOptions(p.club)}</select></label>${field('marketValue','Valor de mercado (CHF)','number')}</div><p class="muted">Ao guardar o jogador noutro clube, a mudança fica registada no histórico. Para uma transferência ou empréstimo com detalhes, completa também <b>Percurso → Transferência / empréstimo actual</b>. Num empréstimo, este campo identifica o clube onde o jogador actua.</p><h3>Posições secundárias</h3><div class="player-positions">${Engine.positions.map(pos=>`<label><input type="checkbox" name="secondary" value="${pos}" ${(p.secondaryPositions||[]).includes(pos)?'checked':''}> ${pos}</label>`).join('')}</div>`)}
 ${pane('jogo',`<div class="game-only-note"><b>VALORES EXCLUSIVOS DA SIMULAÇÃO</b><span>O AVG, o potencial, as skills e a familiaridade posicional abaixo existem apenas para o modo Carreira e para o Match Engine. Não pretendem ser uma avaliação factual ou objectiva de um jogador real.</span></div><div class="game-score-panel"><div><small>AVG DO JOGO</small><strong id="gameOverallValue">${Engine.gameOverall(p)}</strong><span>/ 99</span></div><div>${field('potential','Potencial do jogo (1–99)','number',1,99)}</div></div><p class="muted">O AVG é calculado automaticamente a partir das skills técnicas, mentais e físicas; as mais relevantes para a posição principal têm maior peso. Nos guarda-redes, os atributos específicos de GR têm peso reforçado. Não é editado manualmente.</p>${gameFields}<h3>Familiaridade posicional no jogo</h3><p class="muted">0 = posição totalmente improvisada · 100 = posição natural. A posição principal fica sempre a 100. Estes valores afinam apenas o rendimento no Match Engine.</p><div class="position-familiarity-grid">${Engine.positions.map(pos=>`<label>${pos}<input name="fam-${pos}" type="number" min="0" max="100" step="1" value="${p.positionFamiliarity[pos]??0}" ${pos===p.position?'readonly':''}></label>`).join('')}</div><p class="muted">As skills são valores de equilíbrio do jogo. Os campos de “Perfil de simulação” (consistência, profissionalismo, lesões, reputação e ambição) não entram directamente no AVG; actuam apenas nos sistemas específicos que os utilizam. O motor usa os atributos adequados a cada acção e à posição ocupada.</p>`)}
 ${pane('contrato',`<div class="player-grid">${field('contractStart','Data de início','date')}${field('contractEnd','Data de fim','date')}${field('salary','Salário mensal (CHF)','number',0,1e7)}${select('squadRole','Estatuto no plantel',['Reserva','Rotação','Titular','Jogador-chave'])}${field('releaseClause','Cláusula de rescisão (CHF)','number')}${field('agent','Agente')}</div><p class="muted">As correcções não criam cópias do contrato. Para documentar uma renovação, assinala a opção abaixo antes de guardar.</p><label><input type="checkbox" id="archiveContract"> Arquivar o contrato anterior ao guardar esta renovação</label><p><button type="button" id="openContractHistory">Adicionar, editar ou remover contratos anteriores no Percurso</button></p>`)}
 ${pane('carreira',`${historyEditorMarkup()}<details><summary>Transferência / empréstimo actual</summary><h3>Movimento a registar</h3><div class="movement-box"><p class="muted">Quando alterares o <b>Clube onde joga</b> no Perfil, usa esta área para documentar o movimento. Em Carreira, a data actual da simulação é sugerida; na Base de Dados podes introduzir a data oficial ou deixá-la por indicar.</p><div class="player-grid"><label>Tipo de movimento<select name="moveType" id="moveType">${options(Engine.movementTypes,playerMovement.type)}</select></label><label>Data do movimento<input name="moveDate" type="date" value="${esc(playerMovement.date||'')}"></label> <label>Valor da transferência (CHF)<input name="moveFee" type="number" min="0" max="10000000000" step="1" value="${esc(playerMovement.fee??'')}"></label></div><label>Notas do movimento<textarea name="moveNotes" maxlength="1000">${esc(playerMovement.notes||'')}</textarea></label><section id="movementLoanFields" class="movement-loan-fields"><h4>Detalhes do empréstimo</h4><div class="player-grid"><label>Clube proprietário<select name="moveParentClub"><option value="">Escolher clube…</option>${s.clubs.map(c=>`<option value="${c.id}" ${c.id===playerMovement.parentClub?'selected':''}>${esc(c.name)}</option>`).join('')}</select></label><label>Início do empréstimo<input name="moveLoanStart" type="date" value="${esc(playerMovement.loanStart||'')}"></label><label>Fim do empréstimo<input name="moveLoanEnd" type="date" value="${esc(playerMovement.loanEnd||'')}"></label><label>Taxa de empréstimo (CHF)<input name="moveLoanFee" type="number" min="0" max="10000000000" step="1" value="${esc(playerMovement.loanFee??'')}"></label><label>Compra<select name="movePurchaseType">${options(Engine.purchaseTypes,playerMovement.purchaseType)}</select></label><label>Valor da opção/obrigação (CHF)<input name="movePurchaseFee" type="number" min="0" max="10000000000" step="1" value="${esc(playerMovement.purchaseFee??'')}"></label></div></section></div><h3>Situação de empréstimo actual</h3>${p.loan?`<div class="movement-box"><b>${esc(club(p.loan.parentClub)?.name||'Clube proprietário por identificar')} → ${esc(p.club===null?'Sem clube':club(p.club)?.name||'—')}</b><div class="movement-detail">${esc(p.loan.startDate||'Data inicial por indicar')} · ${esc(p.loan.endDate||'Data final por indicar')}${p.loan.purchaseType&&p.loan.purchaseType!=='Sem opção'?` · ${esc(p.loan.purchaseType)}${p.loan.purchaseFee!==undefined?' '+money(p.loan.purchaseFee):''}`:''}</div></div>`:'<p class="muted">O jogador não tem um empréstimo activo registado.</p>'}</details><h3>Transferências anteriores</h3><div id="pastTransfers"></div>`)}
 ${pane('changes',`<h3>Histórico de alterações</h3><p class="muted">Data real da edição. Regista alterações guardadas a partir desta versão; não reconstrói alterações anteriores. Os resumos longos podem ser abreviados.</p><div id="playerChangeHistory"></div>`)}
 ${pane('stats',`<h3>Época ${s.year}/${String(s.year+1).slice(-2)}</h3><div class="player-summary">${Object.entries({appearances:'Jogos',minutes:'Minutos',goals:'Golos',assists:'Assistências',passes:'Passes tentados',passesCompleted:'Passes completos',recoveries:'Recuperações',shots:'Remates',shotsOnTarget:'Remates à baliza',fouls:'Faltas',yellow:'Amarelos',red:'Expulsões',saves:'Defesas',injuries:'Lesões'}).map(([k,label])=>`<p>${label} <b>${p.stats?.[k]??0}</b></p>`).join('')}</div><p class="muted">Estatísticas actualizadas pelo motor ao concluir cada jornada. Os jogos anteriores ao Match Engine v1 mantêm apenas os dados que já tinham.</p><h3>Épocas concluídas</h3>${p.career?.length?`<div class="table-wrap"><table><thead><tr><th>Época</th><th>Clube no fim da época</th><th>Jogos</th><th>Minutos</th><th>Golos</th><th>Assistências</th></tr></thead><tbody>${p.career.map(h=>`<tr><td>${h.year}/${String(h.year+1).slice(-2)}</td><td>${esc(h.club===null?'Sem clube':club(h.club)?.name||'—')}</td><td>${h.appearances}</td><td>${h.minutes}</td><td>${h.goals??'—'}</td><td>${h.assists??'—'}</td></tr>`).join('')}</tbody></table></div>`:'<p class="muted">Ainda não há épocas registadas para este jogador.</p>'}<p class="muted">O histórico de épocas é criado pela simulação. Os movimentos de clube são documentados separadamente para não perder transferências ocorridas a meio da época.</p>`)}
 ${pane('internacional',`<h3>Histórico por selecção e escalão</h3><p class="muted">Adiciona um país e escalão à tabela. Usa Editar para corrigir um registo. As internacionalizações jovens não contam como jogos da selecção principal. Deixa em branco os valores desconhecidos.</p><div id="internationalRows"></div><div id="internationalTotals" class="player-summary"></div><p class="muted">Dados documentais; não há simulação de selecções.</p>`)}
 ${pane('media',`<fieldset class="rarity-choice"><legend>Raridade do cromo</legend>${[['base','Base'],['silver','Prata'],['gold','Ouro']].map(([v,t])=>`<label><input type="radio" name="theme" value="${v}" ${(p.theme||'base')===v?'checked':''}> ${t}</label>`).join('')}</fieldset><label>Fotografia (redução automática; transparência preservada)<input type="file" id="playerPhoto" accept="image/*,.bmp,.dib,.avif,.svg"></label>${select('crop','Ajuste à área',['contain','cover'])}${photoFrameControls(p)}<button type="button" id="removePhoto">Remover fotografia</button><p class="muted">A fotografia fica incluída no ficheiro ${mode==='database'?'da Mestre':'desta carreira'} e é usada no cromo.</p>`)}
 ${pane('fontes',`<div id="documentSources"></div><label>Notas internas<textarea name="notes" maxlength="5000">${esc(p.notes||'')}</textarea></label>`)}
 </div></div><div class="player-save"><span id="playerError" role="alert"></span><button type="button" id="playerCancel">Cancelar</button><button type="submit" class="primary">Guardar alterações</button></div></form>`;
 drawHistoryEditor();drawPastTransfers();
 drawInternationalRows();
 drawSourceEditor();
 $('resetPhotoFrame').onclick=resetPhotoFrame;
 $('openContractHistory').onclick=()=>{$('pt-carreira').click();$('historyEntry').scrollIntoView({block:'nearest'});};
 const form=$('playerForm');form.oninput=()=>{readPlayerForm();drawPlayer();};form.onchange=()=>{readPlayerForm();drawPlayer();};
 $('playerEditor').querySelectorAll('[data-pane]').forEach(b=>{b.onclick=()=>{document.querySelectorAll('.player-pane').forEach(x=>x.hidden=x.id!=='pp-'+b.dataset.pane);document.querySelectorAll('[data-pane]').forEach(x=>x.setAttribute('aria-selected',String(x===b)));};b.onkeydown=e=>{if(!['ArrowLeft','ArrowRight','Home','End'].includes(e.key))return;e.preventDefault();let tabs=[...document.querySelectorAll('[data-pane]')],i=tabs.indexOf(b);let next=e.key==='Home'?0:e.key==='End'?tabs.length-1:(i+(e.key==='ArrowRight'?1:-1)+tabs.length)%tabs.length;tabs[next].click();tabs[next].focus();};});
 form.addEventListener('invalid',e=>{let pane=e.target.closest('.player-pane');if(pane)$('pt-'+pane.id.slice(3)).click();},true);
 $('playerEditor').querySelectorAll('[data-theme]').forEach(b=>b.onclick=()=>{playerDraft.theme=b.dataset.theme;drawPlayer();});
 const clubSelect=$('playerClub'),statusSelect=form.elements.status,moveType=form.elements.moveType;
 const refreshMovement=()=>{const box=$('movementLoanFields');if(box)box.hidden=moveType.value!=='Empréstimo';};
 clubSelect.onchange=()=>{if(clubSelect.value===''){statusSelect.value='Sem clube';}else if(statusSelect.value==='Sem clube'){statusSelect.value='Activo';}readPlayerForm();drawPlayer();};
 statusSelect.onchange=()=>{if(statusSelect.value==='Sem clube')clubSelect.value='';if(statusSelect.value!=='Emprestado'&&moveType.value==='Empréstimo'&&p.loan)moveType.value='Automático';if(statusSelect.value==='Emprestado'&&moveType.value==='Automático')moveType.value='Empréstimo';readPlayerForm();refreshMovement();drawPlayer();};
 moveType.onchange=()=>{readPlayerForm();if(moveType.value==='Empréstimo')statusSelect.value='Emprestado';refreshMovement();drawPlayer();};refreshMovement();
 const close=()=>{$('playerEditor').close();};$('playerClose').onclick=close;$('playerCancel').onclick=close;$('playerEditor').oncancel=e=>{e.preventDefault();close();};
 let photoRequest=0,photoBusy=false;const photoSubmit=form.querySelector('[type="submit"]');
 $('playerPhoto').onchange=async e=>{const draft=playerDraft,f=e.target.files[0];if(!f)return;const token=++photoRequest;photoBusy=true;playerPhotoBusy=true;photoSubmit.disabled=true;$('playerError').textContent='A optimizar a fotografia…';try{const data=await optimizeImage(f,'portrait');if(playerDraft!==draft||token!==photoRequest||!$('playerEditor').open)return;playerDraft.photo=data;resetPhotoFrame();$('playerError').textContent='Fotografia optimizada · '+Math.round(data.length*3/4/1000)+' KB';drawPlayer();}catch(err){if(playerDraft===draft&&token===photoRequest&&$('playerEditor').open)$('playerError').textContent=err.message;}finally{if(token===photoRequest){photoBusy=false;if(playerDraft===draft)playerPhotoBusy=false;photoSubmit.disabled=false;}}};
 $('removePhoto').onclick=()=>{photoRequest++;photoBusy=false;playerPhotoBusy=false;photoSubmit.disabled=false;$('playerError').textContent='';delete playerDraft.photo;$('playerPhoto').value='';drawPlayer();};
 form.onsubmit=e=>{e.preventDefault();if(photoBusy)return;savePlayerDraft();};
 readPlayerForm();playerDraftBaseline=JSON.stringify(playerDraft);playerMovementBaseline=JSON.stringify(playerMovement);setupPlayerNavigation(id,keepNavigation);if(previousPane)$('pt-'+previousPane)?.click();drawPlayer();if(!$('playerEditor').open)$('playerEditor').showModal();
}
function readPlayerForm(){
 const f=new FormData($('playerForm')),numeric=['photoZoom','photoX','photoY','number','potential','height','weight','marketValue','releaseClause','salary','caps','internationalGoals'];
 for(let [k,v] of f){if(k==='secondary'||k==='club'||k.startsWith('move')||k.startsWith('intl-'))continue;if(k.startsWith('attr-')){playerDraft.attributes[k.slice(5)]=Number(v);continue;}if(k.startsWith('fam-')){playerDraft.positionFamiliarity=playerDraft.positionFamiliarity||{};playerDraft.positionFamiliarity[k.slice(4)]=Number(v);continue;}if(numeric.includes(k)){if(v==='')delete playerDraft[k];else playerDraft[k]=Number(v);}else playerDraft[k]=String(v).trim();}
 readInternationalRows(f);
 const rawClub=f.get('club');playerDraft.club=rawClub===''?null:Number(rawClub);playerDraft.secondaryPositions=f.getAll('secondary');playerDraft.positionFamiliarity=playerDraft.positionFamiliarity||{};playerDraft.positionFamiliarity[playerDraft.position]=100;playerDraft.quality=Engine.gameOverall(playerDraft);playerMovement={type:String(f.get('moveType')||'Automático'),date:String(f.get('moveDate')||''),fee:f.get('moveFee')===''?undefined:Number(f.get('moveFee')),notes:String(f.get('moveNotes')||'').trim(),parentClub:f.get('moveParentClub')===''?undefined:Number(f.get('moveParentClub')),loanStart:String(f.get('moveLoanStart')||''),loanEnd:String(f.get('moveLoanEnd')||''),loanFee:f.get('moveLoanFee')===''?undefined:Number(f.get('moveLoanFee')),purchaseType:String(f.get('movePurchaseType')||'Sem opção'),purchaseFee:f.get('movePurchaseFee')===''?undefined:Number(f.get('movePurchaseFee'))};
}
function drawPlayer(){
 let p=playerDraft,c=p.club===null?null:club(p.club),initials=c?c.name.replace(/FC |AC /g,'').slice(0,2).toUpperCase():'—';let bg=c?.color||'#46515d',theme=['silver','gold'].includes(p.theme)?p.theme:'base';let age=p.birthDate?Engine.age(s,p):undefined,overall=Engine.gameOverall(p),clubName=c?.name||'Sem clube';
 p.quality=overall;
 for(const [key,def] of [['photoZoom',100],['photoX',0],['photoY',0]])if($(key+'Value'))$(key+'Value').textContent=(p[key]??def)+'%';
 $('playerSticker').innerHTML=playerStickerMarkup(p,s);
 if($('gameOverallValue'))$('gameOverallValue').textContent=overall;
 for(const [key,id] of [['nation','nationFlagPreview'],['secondNation','secondNationFlagPreview']]){const el=$(id);if(el){const code=resolveCountry(p[key]);el.innerHTML=code?`${countryFlag(p[key])}<span>${esc(countryName(code))}</span>`:'<span>Sem país seleccionado</span>';}}
 $('playerSummary').innerHTML=`<details><summary>Resumo da simulação</summary><p class="muted">Parâmetros e resultados do jogo; não são dados documentais.</p><p>Fadiga após último jogo <b>${Math.round(p.fatigue||0)}%</b></p><p>Recuperação <b>${p.injuryMatches||0} jornada(s)</b></p><p>Suspensão <b>${p.suspendedMatches||0} jornada(s)</b></p><p>Valor de mercado <b>${p.marketValue===undefined?'—':money(p.marketValue)}</b></p>${p.loan?`<p>Vínculo <b>Emprestado por ${esc(club(p.loan.parentClub)?.name||'—')}</b></p>`:''}<p>AVG do jogo <b>${overall} / 99</b></p><p>Qualidade na posição (jogo) <b>${Engine.roleQuality(p,p.position).toFixed(1)} / 99</b></p><p>Disponibilidade <b>${Engine.eligible(s,p)?'Disponível':'Indisponível'}</b></p><p>Data da simulação <b>${Engine.date(s).split('-').reverse().join('/')}</b></p><p>Potencial do jogo <b>${p.potential??'—'}</b></p></details>`;
 drawPlayerIdentity();
 drawPlayerTimeline();
 drawChangeHistory();
 drawDocumentCompleteness();
 drawInternationalTotals();
 $('playerEditor').querySelectorAll('[data-theme]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.theme===theme)));
}
